// Read original Word table geometry and reuse a selected table without a writing call.
function renderNativeTablePreview(item,editable=false){
 const table=el('table');table.className='source-table-preview';const matrix=[item.headers,...item.rows],layout=item.source_table_layout;
 const merged=layout?.row_count===matrix.length&&layout.grid?.length===matrix[0].length;const origins=new Map(),covered=new Set();
 if(merged)for(const c of layout.cells){origins.set(c.row+':'+c.col,c);for(let r=c.row;r<c.row+c.rowspan;r++)for(let k=c.col;k<c.col+c.colspan;k++)if(r!==c.row||k!==c.col)covered.add(r+':'+k);}
 matrix.forEach((row,ri)=>{const tr=el('tr');row.forEach((text,ci)=>{if(covered.has(ri+':'+ci))return;const spec=origins.get(ri+':'+ci),cell=el(ri<(layout?.header_rows||1)?'th':'td');if(spec){cell.rowSpan=spec.rowspan;cell.colSpan=spec.colspan;}if(editable){const input=el('textarea');input.value=text;input.dataset.row=String(ri-1);input.dataset.col=String(ci);input.setAttribute('aria-label',item.caption+'第'+(ri+1)+'行第'+(ci+1)+'列');input.oninput=()=>editorDirty=true;cell.append(input);}else cell.textContent=text;tr.append(cell);});table.append(tr);});return table;
}
