let imageLibraryProject='',imageLibraryData=null,imageLibraryChoice=null,imageLibraryPage=1,imageLibraryEditingId=null;
const imageLibrary=el('details',undefined,'document-image-library');imageLibrary.id='document-image-library';imageLibrary.append(el('summary','文档图片库 · 从上传资料选择图片并插入'));
imageLibrary.append(el('p','自动识别Word内嵌图片和PDF内嵌位图；组合图、矢量图或扫描页可选“PDF原页”。图片按需转换，不调用模型。选择后放到本章小节末尾或具体段落之后，仍由你统一保存本轮版本。','muted'));
const imageLibraryFile=el('select');imageLibraryFile.setAttribute('aria-label','文档图片来源文件');const imageLibraryKind=el('select');imageLibraryKind.setAttribute('aria-label','文档图件类型');imageLibraryKind.append(new Option('文档内嵌图片','image'),new Option('PDF原页图件（保留完整图文）','page'));
const imageLibraryStatus=el('p',undefined,'muted'),imageLibraryGrid=el('div',undefined,'document-image-grid'),imageLibraryPager=el('div',undefined,'file-bulk-toolbar');
const imageLibraryCount=el('span'),imageLibraryPrev=button('上一页',async()=>{imageLibraryPage--;await loadImageLibrary();}),imageLibraryNext=button('下一页',async()=>{imageLibraryPage++;await loadImageLibrary();});imageLibraryPager.append(imageLibraryPrev,imageLibraryCount,imageLibraryNext);
const imageSelected=el('p','尚未选择图片','muted'),imageCaption=el('input');imageCaption.maxLength=160;imageCaption.setAttribute('aria-label','插入图片的图题');imageCaption.placeholder='图题（可编辑）';
const imageTargetHeading=el('select');imageTargetHeading.setAttribute('aria-label','图片插入小节');const imageTargetParagraph=el('select');imageTargetParagraph.setAttribute('aria-label','图片插入段落');
function documentImageUrl(item,thumb=false){return endpoint('source-images/'+(item.id||item.asset_id)+'/preview')+'?file_id='+encodeURIComponent(item.source_file_id)+(thumb?'&thumb=1':'');}
function chooseDocumentImage(item){imageLibraryEditingId=null;imageInsert.textContent='插入到所选位置';imageLibraryChoice=item;imageCaption.value=item.caption;imageSelected.textContent='已选择：'+item.source_file+' · '+(item.locator||item.source_locator||'')+' · '+item.caption;for(const card of imageLibraryGrid.children)card.classList.toggle('selected',card.dataset.asset===item.id);}
async function loadImageLibrary(){
 if(!selected||!imageLibraryFile.value)return;const project=selected,file=imageLibraryFile.value,kind=imageLibraryKind.value,page=imageLibraryPage;imageLibraryStatus.textContent='正在本地读取图件目录…';
 const data=await api(endpoint('source-images')+'?file_id='+encodeURIComponent(file)+'&kind='+kind+'&page='+page);if(project!==selected||file!==imageLibraryFile.value||kind!==imageLibraryKind.value||page!==imageLibraryPage)return;
 imageLibraryData=data;imageLibraryKind.value=data.kind;imageLibraryPage=data.page;imageLibraryCount.textContent=data.page+' / '+data.pages+' 页';imageLibraryPrev.disabled=data.page<=1;imageLibraryNext.disabled=data.page>=data.pages;
 imageLibraryStatus.textContent='本类别 '+data.total+' 项 · 内嵌图片 '+data.image_count+' 张'+(data.warnings.length?' · '+data.warnings.slice(0,3).join('；'):'');imageLibraryGrid.replaceChildren();
 if(!data.items.length)imageLibraryGrid.append(el('p','没有找到可独立提取的图片；Word中的矢量绘图可先导出PDF，再选择原页。','muted'));
 for(const item of data.items){const card=el('article',undefined,'document-image-card');card.dataset.asset=item.id;card.classList.toggle('selected',item.id===imageLibraryChoice?.id);if(item.supported){const picture=el('img');picture.loading='lazy';picture.src=documentImageUrl(item,true);picture.alt=item.caption;picture.onerror=()=>{picture.alt='图片转换失败，请尝试原页图件';};card.append(picture);}card.append(el('strong',item.caption),el('small',item.locator));if(item.warning)card.append(el('small',item.warning,'muted'));const preview=button('放大预览',()=>{$('#image-preview').src=documentImageUrl(item);$('#image-dialog').showModal();}),select=button('选择此图',()=>chooseDocumentImage(item));preview.disabled=select.disabled=!item.supported||!!current.busy;card.append(preview,select);imageLibraryGrid.append(card);}
}
function imageParagraphOptions(){imageTargetParagraph.replaceChildren(new Option('小节/章节末尾',''));const section=report?.sections[currentChapter];for(const [i,p] of (section?.paragraphs||[]).entries())if((p.heading||section.title)===imageTargetHeading.value)imageTargetParagraph.append(new Option('第'+(i+1)+'段后 · '+p.text.replace(/\s+/g,' ').slice(0,44),String(i)));}
imageLibraryFile.onchange=async()=>{imageLibraryPage=1;imageLibraryKind.value='image';imageLibraryEditingId=null;imageInsert.textContent='插入到所选位置';imageLibraryChoice=null;imageSelected.textContent='尚未选择图片';try{await loadImageLibrary();}catch(error){imageLibraryStatus.textContent=error.message;}};
imageLibraryKind.onchange=async()=>{imageLibraryPage=1;try{await loadImageLibrary();}catch(error){imageLibraryStatus.textContent=error.message;}};imageTargetHeading.onchange=imageParagraphOptions;
imageLibrary.addEventListener('toggle',()=>{if(imageLibrary.open&&!imageLibraryData)loadImageLibrary().catch(error=>imageLibraryStatus.textContent=error.message);});
const imageLibraryReload=button('更新图片库',async()=>{imageLibraryPage=1;await loadImageLibrary();});
const imageInsert=button('插入到所选位置',async()=>{
 if(!imageLibraryChoice)throw Error('请先选择图片');const section=report.sections[currentChapter],item=imageLibraryChoice,index=imageTargetParagraph.value===''?null:Number(imageTargetParagraph.value);
 const data={file_id:item.source_file_id,asset_id:item.id,caption:imageCaption.value,section_id:sectionId(section),heading:imageTargetHeading.value,paragraph_index:index,...(imageLibraryEditingId?{replace_figure_id:imageLibraryEditingId}:{}),...(index!==null?{paragraph_text:section.paragraphs[index].text}:{})};if(editorDirty)await saveSection();await post(endpoint('insert-source-image'),{...data,base_version:current.report_version});imageLibraryEditingId=null;imageInsert.textContent='插入到所选位置';loadedVersion=null;await refresh();notify('图片已放入编辑区；完成本轮修改后统一保存版本。');
},'primary');
imageLibrary.append(imageLibraryFile,imageLibraryKind,imageLibraryReload,imageLibraryStatus,imageLibraryGrid,imageLibraryPager,imageSelected,imageCaption,imageTargetHeading,imageTargetParagraph,imageInsert);
const insertedImagePanel=el('div',undefined,'inserted-document-images');
const renderBeforeDocumentImages=renderEditor;renderEditor=function(){renderBeforeDocumentImages();if(!imageLibrary.isConnected)$('#paragraph-editor').before(imageLibrary);if(!insertedImagePanel.isConnected)imageLibrary.after(insertedImagePanel);
 const section=report.sections[currentChapter],ident=sectionId(section);if(imageLibraryProject!==selected){imageLibraryProject=selected;imageLibraryData=null;imageLibraryChoice=null;imageLibraryPage=1;imageSelected.textContent='尚未选择图片';}
 const chosen=imageLibraryFile.value;imageLibraryFile.replaceChildren(new Option('请选择Word或PDF来源文件',''));for(const file of current.files)if(file.active!==false&&/\.(docx|pdf)$/i.test(file.name))imageLibraryFile.append(new Option(file.name,file.id));imageLibraryFile.value=chosen;if(!imageLibraryFile.value)imageLibraryFile.value=current.files.find(f=>f.active!==false&&f.report_source_confirmed&&/\.docx$/i.test(f.name))?.id||current.files.find(f=>f.active!==false&&/\.docx$/i.test(f.name))?.id||current.files.find(f=>f.active!==false&&/\.pdf$/i.test(f.name))?.id||'';
 if(chosen!==imageLibraryFile.value){imageLibraryData=null;imageLibraryChoice=null;imageSelected.textContent='尚未选择图片';if(imageLibrary.open)loadImageLibrary().catch(error=>imageLibraryStatus.textContent=error.message);}
 const heading=imageTargetHeading.value;imageTargetHeading.replaceChildren();for(const h of [section.title,...(section.subheadings||[])])imageTargetHeading.append(new Option(h,h));imageTargetHeading.value=[...imageTargetHeading.options].some(o=>o.value===heading)?heading:activeEditSubsection||section.title;imageParagraphOptions();imageInsert.disabled=!!current.busy||!!report.chapter_workflow?.[ident]?.locked;
 insertedImagePanel.replaceChildren();if(section.figures?.length)insertedImagePanel.append(el('h4','本章已插入图件'));
 for(const figure of section.figures||[]){const row=el('div',undefined,'inserted-document-image');const thumb=el('img');thumb.loading='lazy';thumb.src=documentImageUrl(figure,true);thumb.alt=figure.caption;const info=el('div');const anchors=section.paragraphs.filter(p=>p.text===figure.paragraph_text);info.append(el('strong',figure.caption),el('small',figure.heading+' · '+(figure.paragraph_text?(anchors.length===1?'指定段落之后':'原段落已变化，请重新选择位置'):'小节末尾')),el('small',figure.source_file+' · '+figure.source_locator));const adjust=button('调整位置/图题',()=>{imageLibrary.open=true;imageLibraryFile.value=figure.source_file_id;imageLibraryKind.value=/^page\[\d+\]$/.test(figure.source_locator)?'page':'image';imageLibraryPage=1;chooseDocumentImage({...figure,id:figure.asset_id,locator:figure.source_locator,supported:true});imageLibraryEditingId=figure.id;imageInsert.textContent='更新此图位置';imageTargetHeading.value=figure.heading;imageParagraphOptions();imageTargetParagraph.value=anchors.length===1?String(section.paragraphs.indexOf(anchors[0])):'';loadImageLibrary().catch(error=>imageLibraryStatus.textContent=error.message);imageLibrary.scrollIntoView({behavior:'smooth',block:'start'});});const remove=button('移除此图',async()=>{if(editorDirty)await saveSection();await post(endpoint('remove-source-image'),{base_version:current.report_version,section_id:ident,figure_id:figure.id});loadedVersion=null;await refresh();notify('已从编辑区移除图片，来源文件保留');});remove.disabled=!!current.busy||!!report.chapter_workflow?.[ident]?.locked||subsectionLocked(figure.heading);adjust.disabled=remove.disabled;row.append(thumb,info,adjust,remove);insertedImagePanel.append(row);}
};
function appendDocumentFigurePreview(preview,index=null){
 const section=report.sections[currentChapter],active=$('#subsection-edit-toolbar select')?.value||'';
 for(const figure of section.figures||[]){if(active&&figure.heading!==active)continue;const matches=section.paragraphs.map((p,i)=>p.text===figure.paragraph_text?i:-1).filter(i=>i>=0);const anchor=figure.paragraph_text&&matches.length===1?matches[0]:null;if(anchor!==index)continue;const box=el('figure',undefined,'report-document-figure'),picture=el('img');picture.loading='lazy';picture.src=documentImageUrl(figure);picture.alt=figure.caption;box.append(picture,el('figcaption',figure.caption));if(figure.paragraph_text&&anchor===null)box.append(el('small','原插入段落已变化，请重新选择位置；导出时将提示待核对。','conflict'));preview.append(box);}
}
